/* The e-class analysis this rule set reasons with (egg §4.1).
 * A rule states an equality; that a value lies in a range is
 * abstract interpretation and cannot be one, so the domain is
 * declared and its hooks are the consumer's. Assembling the
 * struct here is what stops each site that builds a graph from
 * doing it by hand and drifting from the next one.
 *
 * The size is `sizeof` the declared type, so the consumer's own
 * header owns the layout — this file never restates one. That
 * type and these functions must be in scope where this header is
 * included, which is the same requirement the auxiliaries make. */
extern void jav_eq_make(egraph* g, int op, int64_t data,
                    const eg_id* kids, int nkids,
                    void* out, void* user);
extern void jav_eq_join(const void* a, const void* b, void* out, void* user);
extern void jav_eq_modify(egraph* g, eg_id c, const void* d, void* user);

/* Install it. Call before the first eg_add: egraph.h computes a
 * fact as each node is added, and a class created earlier has
 * none. `user` stays the caller's — it is the one thing the
 * grammar cannot know. */
void jav_eqsat_set_analysis(egraph* g, void* user) {
    eg_analysis a;
    a.size   = sizeof(jav_eq_fact_t);
    a.make   = jav_eq_make;
    a.join   = jav_eq_join;
    a.modify = jav_eq_modify;
    a.user   = user;
    eg_set_analysis(g, &a);
}

